    "chapter": "s03_deferred_loading",
    "builds_on": ["s02_tool_dispatch"],
    "adds": [
        "compact deferred tool directory",
        "deterministic tool discovery",
        "session-scoped schema loading",
    ],
    "preserves": ["single-source tool registry", "dispatch boundary"],
}

