@dataclass
class MockResponse:
    """Simulates an LLM response with tool calls or text."""
    tool_calls: list[dict] = field(default_factory=list)
    text: str = ""
    stop_reason: str = "tool_use"  # or "end_turn"

    @property
    def is_tool_use(self) -> bool:
        return len(self.tool_calls) > 0


